// Source-selected red rubric mixed alphabet, all primitive q13 keys,
// latent word boundaries. A full-period and a disjoint eight-consuming lexical anchor
// suffice to enumerate a key; exact minimum-OOV segmentation follows.
#include <bits/stdc++.h>
#include <codecvt>
#include <locale>
using namespace std;
using U=uint64_t;using A=array<int,29>;using K=array<int,13>;
const string sy="0123456789abcdefghijklmnopqrs";
const vector<string> rn={"F","U","TH","O","R","C","G","W","H","N","I","J","EO","P","X","S","T","B","E","M","L","NG","OE","D","A","AE","Y","IA","EA"};
int md(int x){return (x+29)%29;}
string file(const string&p){ifstream f(p);if(!f)throw runtime_error(p);return string(istreambuf_iterator<char>(f),{});}
vector<string> words(const string&s){istringstream f(s);vector<string>v;string w;while(f>>w)v.push_back(w);return v;}
vector<string> fields(const string&s,const string&k){regex re("\""+k+"\"\\s*:\\s*\"([^\"]*)\"");vector<string>v;for(sregex_iterator i(s.begin(),s.end(),re),e;i!=e;++i)v.push_back((*i)[1]);return v;}
vector<string> arrfield(const string&s,const string&k){regex re("\""+k+"\"\\s*:\\s*\\[([^\\]]*)\\]");smatch m;if(!regex_search(s,m,re))throw runtime_error(k);string t=m[1];regex z("\"([0-9a-s]+)\"");vector<string>v;for(sregex_iterator i(t.begin(),t.end(),z),e;i!=e;++i)v.push_back((*i)[1]);return v;}
map<string,double> freq;double fcur=0,totalFreq=0;
struct Node{array<int,29> next{};int word=-1;Node(){next.fill(-1);}};
vector<Node> trie(1);vector<string> lex;vector<double> logp;vector<vector<pair<string,vector<int>>>> by(64);int maxlen=0;
void spell(const string&s,int i,string w){if(i==(int)s.size()){freq[w]+=fcur;return;}for(int n=1;n<=3&&i+n<=(int)s.size();n++){string t=s.substr(i,n);int j=-1;if(n==3){if(t=="ING")j=21;}else for(int x=0;x<29;x++)if(t==rn[x]){j=x;break;}if(j>=0)spell(s,i+n,w+sy[j]);}}
void dictionary(){istringstream f(file("resources/control/english_wordfreq_textblob.txt"));string l;regex re("^([a-z]+)\\s+([0-9]+)$");smatch m;while(getline(f,l)){if(!regex_match(l,m,re))continue;string s=m[1],v,z;fcur=stod(m[2]);for(char c:s)v+=toupper(c);for(int i=0;i<(int)v.size();i++){if(v.substr(i,2)=="QU"){z+="CW";i++;continue;}char c=v[i];z+=c=='V'?'U':c=='K'||c=='Q'?'C':c=='Z'?'S':c;}spell(z,0,"");}if(freq.size()!=38910)throw runtime_error("base dictionary");for(auto&w:words(fields(file("im-results/lp2-shared-gp29-q8-terminal-corrected-fixtures.json"),"added").at(0)))if(!freq.count(w))freq[w]=1;if(freq.size()!=38938)throw runtime_error("dictionary");for(auto&[w,v]:freq)totalFreq+=v+0.1;for(auto&[w,v]:freq){int id=lex.size(),q=0;lex.push_back(w);logp.push_back(log((v+0.1)/totalFreq));vector<int> a;for(char c:w){int x=sy.find(c);a.push_back(x);int n=trie[q].next[x];if(n<0){n=trie.size();trie[q].next[x]=n;trie.emplace_back();}q=n;}trie[q].word=id;maxlen=max(maxlen,(int)w.size());by[w.size()].push_back({w,move(a)});}}
vector<A> bank;vector<string> labels;
void alphabets(){for(string w:{"f8i36jr0fqil5"})for(int f=0;f<2;f++){string order;if(f)order+='0';for(char c:w+sy)if(order.find(c)==string::npos)order+=c;A p{};int z=order.find('0');for(int x=0;x<29;x++)p[x]=md((int)order.find(sy[x])-z);if(find(bank.begin(),bank.end(),p)==bank.end()){bank.push_back(p);labels.push_back(w+(f?":F-first":":rotate"));}}}
U norm(const K&k){int best=0;for(int i=1;i<13;i++)for(int j=0;j<13;j++){int a=k[(i+j)%13],b=k[(best+j)%13];if(a<b){best=i;break;}if(a>b)break;}U x=0;for(int j=0;j<13;j++)x=x*29+k[(best+j)%13];return x;}
K unpack(U x){K k;for(int j=12;j>=0;j--){k[j]=x%29;x/=29;}return k;}
bool primitive(const K&k){return any_of(k.begin()+1,k.end(),[&](int x){return x!=k[0];});}
string encrypt(const string&w,const A&p,const K&k,int j){A ip{};for(int x=0;x<29;x++)ip[p[x]]=x;string c;for(char x:w){int a=sy.find(x);if(!a)c+='0';else{c+=sy[ip[md(p[a]+k[j])]];j=(j+1)%13;}}return c;}
struct Edge{int len,id,phase;};using ED=vector<vector<Edge>>;
ED edges(const string&C,const A&p,const K&k){A ip{};for(int x=0;x<29;x++)ip[p[x]]=x;int mp[13][29];for(int j=0;j<13;j++)for(int x=0;x<29;x++)mp[j][x]=ip[md(p[x]-k[j])];ED out(C.size());for(int start=0;start<(int)C.size();start++){vector<Edge> best(maxlen+1,{-1,-1,-1});for(int phase=0;phase<13;phase++){function<void(int,int,int)> walk=[&](int i,int j,int node){int n=i-start,id=trie[node].word;if(id>=0&&(best[n].id<0||logp[id]>logp[best[n].id]))best[n]={n,id,phase};if(i==(int)C.size()||n==maxlen)return;int x=sy.find(C[i]);if(x==0&&trie[node].next[0]>=0)walk(i+1,j,trie[node].next[0]);int y=mp[j][x];if(y&&trie[node].next[y]>=0)walk(i+1,(j+1)%13,trie[node].next[y]);};walk(start,phase,0);}for(auto e:best)if(e.id>=0){if(encrypt(lex[e.id],p,k,e.phase)!=C.substr(start,e.len))throw runtime_error("edge replay");out[start].push_back(e);}}return out;}
bool truthword(const string&c,const string&t,const A&p,const K&k){for(int j=0;j<13;j++)if(encrypt(t,p,k,j)==c)return true;return false;}
struct Cell{int bad=1000000;double score=-1e100;int prev=-1,word=-2,phase=-1;};
struct Seg{int bad=1000000,count=0,oov=0;double score=-1e100;vector<string> text;};
Seg segment(const string&C,const A&p,const K&k,int lo,int hi,int maxOOV){auto E=edges(C,p,k);int n=C.size(),D=hi+1,B=maxOOV+1;vector<Cell> dp((n+1)*D*B);auto at=[&](int i,int w,int b){return (i*D+w)*B+b;};dp[0]={0,0,-1,-2,-1};auto upd=[&](int q,int r,int bad,double sc,int word,int phase){auto&x=dp[r];if(bad<x.bad||(bad==x.bad&&sc>x.score))x={bad,sc,q,word,phase};};for(int i=0;i<n;i++)for(int w=0;w<hi;w++)for(int b=0;b<B;b++){int q=at(i,w,b);auto z=dp[q];if(z.bad==1000000)continue;for(auto e:E[i])upd(q,at(i+e.len,w+1,b),z.bad,z.score+logp[e.id],e.id,e.phase);if(b<maxOOV)for(int m=1;m<=16&&i+m<=n;m++)upd(q,at(i+m,w+1,b+1),z.bad+m,z.score-6*m-8,-1,-1);}
Seg s;int q=-1;for(int w=lo;w<=hi;w++)for(int b=0;b<B;b++){int r=at(n,w,b);auto z=dp[r];if(z.bad<s.bad||(z.bad==s.bad&&z.score>s.score)){s.bad=z.bad;s.score=z.score;s.count=w;s.oov=b;q=r;}}if(q<0||s.bad==1000000)return s;while(dp[q].prev>=0){auto z=dp[q];int end=q/(D*B),start=z.prev/(D*B);if(z.word<0)s.text.push_back("["+C.substr(start,end-start)+"]");else{s.text.push_back(lex[z.word]);if(encrypt(lex[z.word],p,k,z.phase)!=C.substr(start,end-start))throw runtime_error("segment replay");}q=z.prev;}reverse(s.text.begin(),s.text.end());return s;}

struct Candidate{int alphabet;U key;Seg fit;};
struct Stats{U trials=0,fragments=0,fullInc=0,fullKeys=0,candidates=0;vector<Candidate> fits;};
struct Interval{int minEnd=INT_MAX,maxStart=-1;};
struct Full{U id;int start,end;};
Stats recover(const string&C){Stats s;vector<int> c;for(char x:C)c.push_back(sy.find(x));for(int b=0;b<(int)bank.size();b++){auto&p=bank[b];unordered_map<U,Interval> index;index.reserve(5000000);vector<Full> full;
for(int end=8;end<=(int)c.size();end++)for(int L=8;L<=min(maxlen,end);L++){int start=end-L,nz=0;for(int j=start;j<end;j++)nz+=c[j]!=0;if(nz<8)continue;for(auto&item:by[L]){s.trials++;auto&w=item.second;K k;k.fill(-1);int j=0;bool ok=true;for(int i=0;i<L;i++){if(!w[i]){if(c[start+i]){ok=false;break;}continue;}int d=md(p[c[start+i]]-p[w[i]]),h=j%13;if(k[h]>=0&&k[h]!=d){ok=false;break;}k[h]=d;j++;}if(!ok||j<8)continue;U id=0;for(int i=0;i<8;i++)id=id*29+k[i];auto&x=index[id];x.minEnd=min(x.minEnd,end);x.maxStart=max(x.maxStart,start);if(j>=13&&primitive(k)){full.push_back({norm(k),start,end});s.fullInc++;}}}
s.fragments+=index.size();unordered_set<U> all,qual;for(auto&x:full){all.insert(x.id);if(qual.count(x.id))continue;auto k=unpack(x.id);bool hit=false;for(int j=0;j<13;j++){U h=0;for(int t=0;t<8;t++)h=h*29+k[(j+t)%13];auto it=index.find(h);if(it!=index.end()&&(it->second.minEnd<=x.start||it->second.maxStart>=x.end)){hit=true;break;}}if(hit)qual.insert(x.id);}s.fullKeys+=all.size();s.candidates+=qual.size();for(U id:qual){auto k=unpack(id);auto a=segment(C,p,k,90,135,6);if(a.bad<=45)s.fits.push_back({b,id,move(a)});}}
sort(s.fits.begin(),s.fits.end(),[](auto&a,auto&b){if(a.fit.bad!=b.fit.bad)return a.fit.bad<b.fit.bad;if(a.fit.score!=b.fit.score)return a.fit.score>b.fit.score;if(a.alphabet!=b.alphabet)return a.alphabet<b.alphabet;return a.key<b.key;});return s;}
template<class T>string ar(const T&v){string s="[";for(auto x:v){if(s.size()>1)s+=",";s+=to_string(x);}return s+"]";}
string joined(const vector<string>&v){string s;for(auto&w:v)s+=w;return s;}
string strarr(const vector<string>&v){string s="[";for(auto&w:v){if(s.size()>1)s+=",";s+='"'+w+'"';}return s+"]";}
string original(){wstring_convert<codecvt_utf8<char32_t>,char32_t> cv;auto u=cv.from_bytes(file("resources/transcriptions/lp2-image-corrected.txt"));u32string runes=U"ᚠᚢᚦᚩᚱᚳᚷᚹᚻᚾᛁᛄᛇᛈᛉᛋᛏᛒᛖᛗᛚᛝᛟᛞᚪᚫᚣᛡᛠ";int page=0;string s;for(auto c:u){if(c==U'%'){if(++page>=3)break;continue;}size_t i=runes.find(c);if(i!=u32string::npos)s+=sy[i];}if(s.size()!=729||s.substr(0,13)!="f8i36jr0fqil5")throw runtime_error("opening source "+s.substr(0,13)+" "+to_string(s.size()));return s.substr(13);}
string native(string w){string s,v;for(char c:w)s+=toupper(c);for(int i=0;i<(int)s.size();i++){if(s.substr(i,2)=="QU"){v+="CW";i++;continue;}char c=s[i];v+=c=='V'?'U':c=='K'||c=='Q'?'C':c=='Z'?'S':c;}string z;for(int i=0;i<(int)v.size();){bool found=false;for(int l=min(3,(int)v.size()-i);l>=1&&!found;l--){string q=v.substr(i,l);int j=-1;if(l==3){if(q=="ING")j=21;}else for(int k=0;k<29;k++)if(q==rn[k]){j=k;break;}if(j>=0){z+=sy[j];i+=l;found=true;}}if(!found)return "";}return z;}
struct Donor{vector<string>T,H;string label;int start;};
Donor donor(int k){vector<string> paths={"resources/control/emerson_essays_2944.txt","resources/control/shakespeare_first300k.txt","resources/control/gibran_prophet_58585.txt"};for(int off=0;off<3;off++){string path=paths[(k+off)%3],s=file(path);regex re("[A-Za-z]+");vector<string> w;for(sregex_iterator i(s.begin(),s.end(),re),e;i!=e;++i){auto x=native((*i)[0]);if(x.size())w.push_back(x);}vector<int> L(1),O(1),Bad(1),A8(1),A13(1);for(auto&x:w){int n=count_if(x.begin(),x.end(),[](char c){return c!='0';});bool in=freq.count(x);L.push_back(L.back()+x.size());O.push_back(O.back()+!in);Bad.push_back(Bad.back()+(!in?x.size():0));A8.push_back(A8.back()+(in&&n>=8));A13.push_back(A13.back()+(in&&n>=13));}
for(int i=700+k*400;i<(int)w.size();i++){auto j=lower_bound(L.begin()+i,L.end(),L[i]+515);if(j==L.end()||*j!=L[i]+515)continue;int c=j-L.begin();auto z=lower_bound(j,L.end(),L[i]+716);if(z==L.end()||*z!=L[i]+716)continue;int end=z-L.begin();if(c-i<90||c-i>135||end-c<30||end-c>60||O[c]-O[i]>6||Bad[c]-Bad[i]>45||O[end]-O[c]>4||A13[c]-A13[i]<1||A8[c]-A8[i]<2)continue;return {{w.begin()+i,w.begin()+c},{w.begin()+c,w.begin()+end},path,i};}}throw runtime_error("no suitable literary anchor window");}
int main(int argc,char**argv){dictionary();alphabets();string mode=argc>1?argv[1]:"0";bool control=mode!="original";string C,Z;vector<string>T,H,TC,HC;K tk{};int tb=-1;string source;int sourceStart=-1;
if(control){int i=stoi(mode);auto d=donor(i);T=d.T;H=d.H;source=d.label;sourceStart=d.start;mt19937 rng(0x13a02900u+i);tb=i%(int)bank.size();for(auto&x:tk)x=rng()%29;if(!primitive(tk))throw runtime_error("nonprimitive");for(auto&w:T)TC.push_back(encrypt(w,bank[tb],tk,rng()%13));for(auto&w:H)HC.push_back(encrypt(w,bank[tb],tk,rng()%13));C=joined(TC);Z=joined(HC);}else{auto s=original();C=s.substr(0,515);Z=s.substr(515);}
if(C.size()!=515||Z.size()!=201)throw runtime_error("length");auto R=recover(C);ostringstream o;o<<"{\"mode\":\""<<mode<<"\",\"source\":\""<<source<<"\",\"sourceStart\":"<<sourceStart<<",\"bank\":"<<bank.size()<<",\"dict\":"<<lex.size()<<",\"trials\":"<<R.trials<<",\"fragments\":"<<R.fragments<<",\"full_incidences\":"<<R.fullInc<<",\"full_keys\":"<<R.fullKeys<<",\"joined_candidates\":"<<R.candidates<<",\"fit_count\":"<<R.fits.size()<<",\"fits\":[";int rank=-1,heldTruth=0;for(int i=0;i<(int)R.fits.size();i++){auto&x=R.fits[i];if(control&&x.alphabet==tb&&x.key==norm(tk)){rank=i+1;for(int j=0;j<(int)H.size();j++)heldTruth+=truthword(HC[j],H[j],bank[x.alphabet],unpack(x.key));}if(i>=5)continue;auto d=segment(Z,bank[x.alphabet],unpack(x.key),30,60,4);if(i)o<<",";o<<"{\"alphabet\":"<<x.alphabet<<",\"label\":\""<<labels[x.alphabet]<<"\",\"pi\":"<<ar(bank[x.alphabet])<<",\"key\":"<<ar(unpack(x.key))<<",\"train_bad\":"<<x.fit.bad<<",\"train_words\":"<<x.fit.count<<",\"train_score\":"<<x.fit.score<<",\"held_bad\":"<<d.bad<<",\"held_words\":"<<d.count<<",\"held_score\":"<<d.score<<",\"train_path\":"<<strarr(x.fit.text)<<",\"held_path\":"<<strarr(d.text)<<"}";}o<<"],\"exact_rank\":"<<rank<<",\"held_truth\":"<<heldTruth<<",\"held_count\":"<<H.size()<<"}";cout<<"FINAL "<<o.str()<<endl;if(const char*p=getenv("SFT_OUTPUT")){ofstream f(p);f<<o.str()<<endl;}return 0;}
